import Foundation
import NIO
import NIOHTTP1

// Background job worker for Kubernetes - handles file processing tasks
// Exposes a health/metrics endpoint for k8s probes

final class JobWorker {
    private let group: MultiThreadedEventLoopGroup
    private let bootstrap: ServerBootstrap
    private let workDir: String
    private let metricsPath: String

    struct WorkerConfig {
        let port: Int
        let workDirectory: String
        let metricsEndpoint: String
        let enableDiagnostics: Bool
        let allowedPrefixes: [String]
    }

    init(config: WorkerConfig) {
        self.group = MultiThreadedEventLoopGroup(numberOfThreads: System.coreCount)
        self.workDir = config.workDirectory
        self.metricsPath = config.metricsEndpoint

        self.bootstrap = ServerBootstrap(group: group)
            .serverChannelOption(ChannelOptions.backlog, value: 256)
            .childChannelInitializer { channel in
                channel.pipeline.configureHTTPServerPipeline().flatMap {
                    channel.pipeline.addHandler(
                        HealthHandler(
                            workDir: config.workDirectory,
                            metricsPath: config.metricsEndpoint,
                            diagnosticsEnabled: config.enableDiagnostics,
                            allowedPrefixes: config.allowedPrefixes
                        )
                    )
                }
            }
    }

    func start(port: Int) throws {
        let channel = try bootstrap.bind(host: "0.0.0.0", port: port).wait()
        print("Worker listening on port \(port)")
        try channel.closeFuture.wait()
    }
}

final class HealthHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let workDir: String
    private let metricsPath: String
    private let diagnosticsEnabled: Bool
    private let allowedPrefixes: [String]

    init(workDir: String, metricsPath: String, diagnosticsEnabled: Bool, allowedPrefixes: [String]) {
        self.workDir = workDir
        self.metricsPath = metricsPath
        self.diagnosticsEnabled = diagnosticsEnabled
        self.allowedPrefixes = allowedPrefixes
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)
        guard case .head(let request) = reqPart else { return }

        let path = sanitizePath(request.uri)

        switch path {
        case "/healthz":
            respondOK(context: context, body: "{\"status\":\"healthy\"}")
        case "/readyz":
            respondOK(context: context, body: "{\"status\":\"ready\"}")
        case _ where path.hasPrefix(metricsPath):
            handleMetrics(context: context, path: path)
        case _ where path.hasPrefix("/diag"):
            handleDiagnostics(context: context, path: path)
        default:
            respond404(context: context)
        }
    }

    private func sanitizePath(_ uri: String) -> String {
        // Remove query parameters and fragments
        let cleaned = uri.split(separator: "?").first.map(String.init) ?? uri
        // Normalize double slashes
        return cleaned.replacingOccurrences(of: "//", with: "/")
    }

    private func isPathAllowed(_ requestedPath: String) -> Bool {
        let resolved = resolveAndValidate(requestedPath)
        let normalizedWork = resolveAndValidate(workDir)

        // Check if resolved real path is within work directory
        guard resolved.hasPrefix(normalizedWork) else { return false }

        // Check against allowed prefixes within work directory
        let relativePath = String(resolved.dropFirst(normalizedWork.count))
        return allowedPrefixes.contains { prefix in
            relativePath.hasPrefix(prefix)
        }
    }

    private func resolveAndValidate(_ path: String) -> String {
        // Use realpath to fully resolve ALL symlinks in the path
        // This prevents symlink-based traversal attacks
        let fm = FileManager.default
        guard let realPath = fm.destinationOfSymbolicLink(atFullResolution: path) else {
            // If we can't resolve, use standardized URL path with symlink resolution
            let url = URL(fileURLWithPath: path).resolvingSymlinksInPath()
            return url.path
        }
        return realPath
    }

    private func handleDiagnostics(context: ChannelHandlerContext, path: String) {
        guard diagnosticsEnabled else {
            respond404(context: context)
            return
        }

        // Extract the sub-path after /diag
        let subPath = String(path.dropFirst("/diag".count))
        let targetPath = workDir + subPath

        // Security: validate the REAL path after symlink resolution is allowed
        guard isPathAllowed(targetPath) else {
            respond403(context: context)
            return
        }

        let fm = FileManager.default
        var isDir: ObjCBool = false

        guard fm.fileExists(atPath: targetPath, isDirectory: &isDir) else {
            respond404(context: context)
            return
        }

        if isDir.boolValue {
            // List directory contents for diagnostics
            if let contents = try? fm.contentsOfDirectory(atPath: targetPath) {
                let listing = contents.map { entry -> String in
                    var entryIsDir: ObjCBool = false
                    fm.fileExists(atPath: targetPath + "/" + entry, isDirectory: &entryIsDir)
                    let suffix = entryIsDir.boolValue ? "/" : ""
                    return "  \(entry)\(suffix)"
                }.joined(separator: "\n")
                respondOK(context: context, body: "Directory: \(subPath)\n\(listing)")
            } else {
                respond500(context: context)
            }
        } else {
            // Return file metadata only
            if let attrs = try? fm.attributesOfItem(atPath: targetPath) {
                let size = attrs[.size] as? Int64 ?? 0
                let modified = attrs[.modificationDate] as? Date ?? Date()
                respondOK(context: context, body: "File: \(subPath)\nSize: \(size)\nModified: \(modified)")
            } else {
                respond500(context: context)
            }
        }
    }

    private func handleMetrics(context: ChannelHandlerContext, path: String) {
        let metrics = """
        # HELP worker_jobs_processed Total jobs processed
        # TYPE worker_jobs_processed counter
        worker_jobs_processed 42
        # HELP worker_jobs_failed Total jobs failed  
        # TYPE worker_jobs_failed counter
        worker_jobs_failed 3
        """
        respondOK(context: context, body: metrics)
    }

    private func respondOK(context: ChannelHandlerContext, body: String) {
        let buffer = context.channel.allocator.buffer(string: body)
        let head = HTTPResponseHead(version: .http1_1, status: .ok)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.write(wrapOutboundOut(.body(.byteBuffer(buffer))), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func respond403(context: ChannelHandlerContext) {
        let head = HTTPResponseHead(version: .http1_1, status: .forbidden)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func respond404(context: ChannelHandlerContext) {
        let head = HTTPResponseHead(version: .http1_1, status: .notFound)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func respond500(context: ChannelHandlerContext) {
        let head = HTTPResponseHead(version: .http1_1, status: .internalServerError)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }
}

// Extension to resolve symlinks fully
extension FileManager {
    func destinationOfSymbolicLink(atFullResolution path: String) -> String? {
        // Iteratively resolve symlinks until we reach a real path
        var currentPath = path
        var seen = Set<String>()
        while let dest = try? destinationOfSymbolicLink(atPath: currentPath) {
            let resolved = dest.hasPrefix("/") ? dest : (currentPath as NSString).deletingLastPathComponent + "/" + dest
            let standardized = URL(fileURLWithPath: resolved).standardized.path
            if seen.contains(standardized) { return nil } // circular symlink
            seen.insert(standardized)
            currentPath = standardized
        }
        return URL(fileURLWithPath: currentPath).standardized.path
    }
}

// Entry point
let config = JobWorker.WorkerConfig(
    port: 8080,
    workDirectory: ProcessInfo.processInfo.environment["WORK_DIR"] ?? "/var/worker/data",
    metricsEndpoint: "/metrics",
    enableDiagnostics: ProcessInfo.processInfo.environment["ENABLE_DIAG"] == "true",
    allowedPrefixes: ["/jobs", "/queue", "/tmp"]
)

let worker = JobWorker(config: config)
try worker.start(port: config.port)
